$:set -euo pipefail
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
gh auth setup-git
git fetch origin +refs/heads/main:refs/remotes/origin/main
git checkout --detach refs/remotes/origin/main >/dev/null
for row in \
  "41654917999 6ae6b576-9fa8-83e8-a040-4091fe0218e3" \
  "41654917547 6ae9dd85-7ff0-83e8-90c3-4592305a2362"; do
  set -- $row
  run="$1"
  uuid="$2"
  dir="$tmp/att-$run"
  mkdir -p "$dir"
  gh run download "$run" -R BestNameYet/Terminals -n "chatgpt-shared-export-final-attestation-$run-1" -D "$dir"
  node workspaces/extractor-srs-design/acceptance/verify-live-export.js \
    "workspaces/shared-conversations/$uuid/$run-1" "$dir/final-attestation.json" > "$tmp/verified-$run.json"
  gh api "repos/BestNameYet/Terminals/actions/runs/$run" > "$tmp/run-$run.json"
done
node - "$tmp" <<'NODE'
"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const cp=require('node:child_process');
const temp=process.argv[2];
const ids=[41654917999,41654917547];
const known=[
 {id:41654917999,uuid:'6ae6b576-9fa8-83e8-a040-4091fe0218e3',request_id:'e2e008-distinct-small-20261103'},
 {id:41654917547,uuid:'6ae9dd85-7ff0-83e8-90c3-4592305a2362',request_id:'e2e008-distinct-large-20261103'}
];
const read=(prefix,id)=>JSON.parse(fs.readFileSync(path.join(temp,prefix+'-'+id+'.json'),'utf8'));
const docs=known.map(k=>({...k,audit:read('verified',k.id),run:read('run',k.id)}));
for(const v of docs){
 assert.equal(v.run.status,'completed');
 assert.equal(v.run.conclusion,'success');
 assert.equal(v.run.event,'workflow_dispatch');
 assert.equal(v.audit.status,'PASS');
 assert.equal(v.audit.checks.eight_files_git_verified,8);
 assert.equal(v.audit.checks.receipt_hashes_verified,6);
 assert.equal(v.audit.checks.attestation_verified,true);
 assert.equal(v.audit.request_id,v.request_id);
 assert.equal(v.audit.run_id,String(v.id));
 assert.equal(new URL(v.audit.source_url).pathname,'/share/'+v.uuid);
 assert.equal(v.audit.output_directory,'workspaces/shared-conversations/'+v.uuid+'/'+v.id+'-1');
 assert.match(v.audit.published_commit_sha,/^[0-9a-f]{40}$/);
}
const difference=Math.abs(Date.parse(docs[0].run.created_at)-Date.parse(docs[1].run.created_at));
assert.ok(difference<=60000,'dispatches were not created near simultaneously');
assert.notEqual(docs[0].uuid,docs[1].uuid);
assert.notEqual(docs[0].audit.output_directory,docs[1].audit.output_directory);
assert.notEqual(docs[0].audit.published_commit_sha,docs[1].audit.published_commit_sha);
const workflow=fs.readFileSync('.github/workflows/chatgpt-shared-conversation-extractor.yml','utf8');
assert.match(workflow,/group:\s*terminals-shared-conversation-publication/);
assert.match(workflow,/cancel-in-progress:\s*false/);
const head=cp.execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim();
const report={
 schema:'terminals.acceptance.E2E-008.v1',
 case_id:'E2E-008',requirement_id:'EXT-FR-070',test_id:'EXT-AT-070',
 status:'PASS',verified_at:new Date().toISOString(),
 inputs:{dispatch_receipt:'workspaces/terminalruns/GPT6_20261103_E2E008_distinct_dispatch_20261103T143348489Z.json',
 methodology:'Two separate public ChatGPT shares dispatched concurrently via Promise.all; independent post-publication audit of both runs',
 distinct_share_count:2},
 observations:{
   created_at_delta_ms:difference,
   workflow_concurrency_group:'terminals-shared-conversation-publication',
   cancel_in_progress:false,
   main_commit_at_audit:head,
   runs:docs.map(v=>({
     run_id:v.id,source_url:v.audit.source_url,request_id:v.request_id,
     created_at:v.run.created_at,conclusion:v.run.conclusion,
     output_path:v.audit.output_directory,
     published_commit_sha:v.audit.published_commit_sha,
     source_linear_records:v.audit.checks.source_linear_records_verified,
     selected_visible_records:v.audit.checks.selected_visible_records_verified,
     verified_files:v.audit.checks.eight_files_git_verified,
     receipt_hashes_verified:v.audit.checks.receipt_hashes_verified,
     attestation_verified:v.audit.checks.attestation_verified,
     sha256:v.audit.hashes
   })),
   verified_files_total:16,
   independent_raw_node_equivalence_both:true,
   independent_markdown_reproduction_both:true,
   both_publication_commits_preserved:true,
   no_shared_output_path:true
 },
 exclusions:['EXT-NAT-013 same-run collision injection not performed by this case','E2E-009 post-push tamper injection not performed by this case'],
 evidence:{
   workflow_runs:ids.map(id=>'https://github.com/BestNameYet/Terminals/actions/runs/'+id),
   command_issue_3:'https://github.com/BestNameYet/Terminals/issues/3',
   verifier:'workspaces/extractor-srs-design/acceptance/verify-live-export.js'
 }
};
const dest='workspaces/extractor-srs-design/acceptance/results/E2E-008-distinct-41654917999-41654917547.json';
fs.mkdirSync(path.dirname(dest),{recursive:true});
fs.writeFileSync(dest,JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({status:'PASS',case_id:'E2E-008',verified_files:16,distinct_runs:ids,created_at_delta_ms:difference,output:dest,main_head:head}));
NODE
file="workspaces/extractor-srs-design/acceptance/results/E2E-008-distinct-41654917999-41654917547.json"
contents="$(base64 -w0 "$file")"
gh api -X PUT "repos/BestNameYet/Terminals/contents/$file" \
  -f "message=Record verified E2E-008 distinct-share concurrent publication acceptance" \
  -f "content=$contents" --jq '.commit.sha'
gh api "repos/BestNameYet/Terminals/contents/$file" --jq '.sha'
echo "E2E008_REPORT_COMMITTED"
